{"action_type":"WriteFile","target":"stopwatch.html","arguments":{"content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Stopwatch</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            font-family: Arial, sans-serif;
        }
        #stopwatch {
            font-size: 48px;
        }
    </style>
</head>
<body>
    <div id="stopwatch">00:00.00</div>
    <button onclick="startStopwatch()">Start</button>
    <button onclick="resetStopwatch()" disabled>Reset</button>
    <script>
        let startTime, elapsedTime = 0;
        let running = false;
        const stopwatchElement = document.getElementById('stopwatch');

        function startStopwatch() {
            if (running) return;
            running = true;
            startTime = performance.now() - elapsedTime;
            updateStopwatch();
            setInterval(updateStopwatch, 10);
        }

        function resetStopwatch() {
            running = false;
            elapsedTime = 0;
            stopwatchElement.textContent = '00:00.00';
            document.querySelector('button[onclick="resetStopwatch()"]').disabled = true;
        }

        function updateStopwatch() {
            if (!running) return;
            const currentTime = performance.now();
            elapsedTime = currentTime - startTime;
            const minutes = Math.floor(elapsedTime / 60000);
            const seconds = Math.floor((elapsedTime % 60000) / 1000);
            const milliseconds = Math.floor((elapsedTime % 1000) / 10);
            stopwatchElement.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}.${String(milliseconds).padStart(2, '0')}`;
        }
    </script>
</body>
</html>"},"reason":"A simple HTML file to display and control a stopwatch."}
